// Партия 5 (финальная) синхронизации справочник -> календарь: декоративные
// кустарники (bereskleet, doren, siren, zhimolost) и летники (barhatcy,
// petuniya, kalendula, nasturciya). У кустарников блок «Календарь работ по
// культуре» состоял из общих строк «роза/спирея/ягодные», у летников — только
// посев; .md расписывает подкормки, поливы, обрезку на кору, омоложение,
// прищипку, удаление отцветшего, сбор семян.
//
// Базовый регион — средняя полоса; сдвиг месяца для юга / Урал-Сибири / СЗ
// как в партиях 2-4.
//
// Источники (веб-поиск, сентябрь 2026):
// - Сирень: сразу после цветения (2-3 недели) — выломать отцветшие метёлки до
//   пары почек, лёгкая формирующая обрезка (только летом, не осенью),
//   фосфорно-калийная подкормка без избытка азота, поросль вырезают по уровню
//   почвы несколько раз за сезон:
//   garshinka.ru/blog/siren-posle-cveteniya..., botanichka.ru/article/obrezka-sireni-vidy-i-pravila
// - Жимолость съедобная: санитарная обрезка рано весной до набухания почек или
//   после листопада; прореживание с 7-8 лет, омоложение старше 15 лет вырезкой
//   старых ветвей на сильный прикорневой побег; тля/клещ/щитовка — Актара,
//   Карбофос, Биотлин после сбора; бурая пятнистость — Хом:
//   antonovsad.ru/uhod-za-zhimolostyu-vesnoy-...-3257, floristics.info/ru/stati/sad/2406
// - Дёрен ради яркой коры — радикальная обрезка ранней весной («на пень» раз в
//   2-3 года или треть старых ветвей ежегодно); влаголюбив — согласовано с
//   docs/plants-src/doren.md
// - Петуния «прожорлива» — комплексное удобрение для цветущих каждые 10-14
//   дней, прищипка и повторная обрезка вытянувшихся плетей на треть, удаление
//   отцветшего для цветения до заморозков; бархатцы/календула/настурция на
//   богатой почве жируют, подкормки минимальны:
//   floristics.info/ru/stati/sadovodstvo/7245-petuniya-prishchipka-podkormka-i-pikirovka,
//   bona-forte.ru/laboratories/life-hacking/330-petuniya-...

const path = require('path');
const XLSX = require('xlsx');

const XLSX_PATH = path.resolve(__dirname, '..', '..', 'garden-data.xlsx');
const wb = XLSX.readFile(XLSX_PATH);
const calRows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar']);

const MONTH_IDS = ['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentyabr','oktyabr','noyabr','dekabr'];
const MONTH_NAMES = ['ЯНВАРЬ','ФЕВРАЛЬ','МАРТ','АПРЕЛЬ','МАЙ','ИЮНЬ','ИЮЛЬ','АВГУСТ','СЕНТЯБРЬ','ОКТЯБРЬ','НОЯБРЬ','ДЕКАБРЬ'];

function shifted(baseIdx, region) {
  if (region === 'srednyaya-polosa' || region === 'severo-zapad') return baseIdx;
  const season = baseIdx <= 4 ? 'spring' : (baseIdx <= 7 ? 'summer' : 'autumn');
  const map = { yug: { spring:-1, summer:-1, autumn:+1 }, 'ural-sibir': { spring:+1, summer:+1, autumn:-1 } };
  return Math.max(0, Math.min(11, baseIdx + map[region][season]));
}

const SRC = 'garshinka.ru/blog/siren-posle-cveteniya; botanichka.ru/article/obrezka-sireni-vidy-i-pravila; antonovsad.ru/uhod-za-zhimolostyu-vesnoy-3257; floristics.info/ru/stati/sad/2406; floristics.info/ru/stati/sadovodstvo/7245-petuniya-prishchipka-podkormka; bona-forte.ru/laboratories/life-hacking/330-petuniya';

// [baseMonthIdx, workType, [plants], text]
const BASE = [
  // ---- сирень ----
  [5, 'udobrenie', ['siren'],
    'После цветения сирени (в ближайшие 2-3 недели) — фосфорно-калийная подкормка без избытка азота; ранней весной — азотная. Сирень не выносит кислых почв: раз в 2-3 года подсыпают золу или доломитовую муку.'],
  [5, 'obrezka', ['siren'],
    'Корневую поросль сирени (у корнесобственной) и дикую поросль от подвоя (у привитой) вырезают по уровню почвы или чуть глубже несколько раз за сезон — иначе куст израстает и слабеет. Формирующую обрезку ведут только летом, не осенью.'],

  // ---- жимолость съедобная ----
  [2, 'obrezka', ['zhimolost'],
    'Санитарная обрезка жимолости — рано весной до набухания почек либо после листопада: сухие, поломанные и лежащие на земле ветви. С 7-8 лет — прореживание загущающих нулевых побегов; старше 15 лет — омоложение вырезкой старых скелетных ветвей на сильный прикорневой побег или боковое ответвление.'],
  [4, 'obrabotka', ['zhimolost'],
    'От тли (скручивание и пожелтение верхушек), жимолостного клеща и щитовки — инсектоакарицид (Актара, Биотлин) сразу после сбора урожая, не в плодоношение; от бурой пятнистости листьев — медьсодержащий препарат («Хом»).'],
  [7, 'udobrenie', ['zhimolost'],
    'После сбора урожая — фосфорно-калийная подкормка жимолости (закладка цветочных почек будущего года идёт с конца лета); осенью в приствольный круг — перегной или компост с лёгкой заделкой.'],
  [9, 'mulcha', ['zhimolost'],
    'Мульчирование приствольного круга жимолости перегноем, компостом или щепой слоем 5-8 см — корни поверхностные, страдают от перегрева и пересыхания; мульчу обновляют весной и осенью.'],

  // ---- бересклет ----
  [4, 'udobrenie', ['bereskleet'],
    'Бересклету — весенняя подкормка комплексным удобрением, на бедной почве повторно в начале лета. Пестролистные формы на ярком солнце окрашены контрастнее, но требуют больше влаги.'],
  [5, 'obrabotka', ['bereskleet'],
    'Бересклет — сильный магнит для тли и паутинного клеща (его сажают как растение-ловушку рядом с плодовыми): регулярный осмотр, смыв струёй воды, инсектицид/акарицид при массовом заселении; от мучнистой росы и пятнистостей — фунгицид.'],
  [6, 'poliv', ['bereskleet'],
    'Бересклету — полив в засуху (молодым обязательно) и мульча приствольного круга; при сильном пересыхании раньше окрашивается осенью, но может сбросить лист.'],
  [7, 'obrezka', ['bereskleet'],
    'Формирующую стрижку бересклета (изгороди, бордюры, шары) ведут в конце мая - июне и при необходимости повторно в конце лета — хорошо переносит стрижку и загущается.'],
  [9, 'ukrytie', ['bereskleet'],
    'Молодые посадки бересклета и вечнозелёные виды (б. Форчуна) на зиму мульчируют и прикрывают лапником — защита от выпревания и весеннего ожога; взрослые листопадные виды зимостойки.'],

  // ---- дёрен ----
  [2, 'obrezka', ['doren'],
    'Дёрен ради яркой коры обрезают радикально ранней весной: раз в 2-3 года «на пень» (10-20 см) либо ежегодно вырезают треть самых старых ветвей — молодой прирост окрашен ярче всего. Без обрезки куст оголяется снизу и кора тускнеет.'],
  [4, 'udobrenie', ['doren'],
    'Дёрену — весенняя азотная подкормка для мощного прироста (его же обрезают на кору); пестролистные сорта на солнце ярче, в тени зеленеют.'],
  [5, 'poliv', ['doren'],
    'Дёрен влаголюбив (в природе растёт по берегам): полив в засуху, особенно молодым и после обрезки «на пень»; мульча. В сушь мельчает лист.'],
  [6, 'obrabotka', ['doren'],
    'От мучнистой росы (белый налёт в загущённых и притенённых посадках) и тли на молодом приросте дёрена — фунгицид и инсектицид; прореживание для проветривания.'],

  // ---- летники: петуния, бархатцы, календула, настурция ----
  [4, 'obrezka', ['petuniya','barhatcy','nasturciya'],
    'Прищипка рассады петунии, высокорослых бархатцев и настурции над 4-5-м листом при высадке — кустистость и обильное ветвление; у петунии прищипку повторяют по мере отрастания плетей.'],
  [5, 'udobrenie', ['petuniya','barhatcy','kalendula','nasturciya'],
    'Петунии в цвету — комплексное удобрение для цветущих каждые 10-14 дней (культура очень «прожорлива»). Бархатцы, календула и настурция на богатой почве жируют в ущерб цветению — им подкормки минимальны, азот исключают.'],
  [5, 'obrezka', ['petuniya','barhatcy','kalendula','nasturciya'],
    'Регулярное удаление отцветших цветков и завязей у летников продлевает цветение до заморозков и не даёт истощающего самосева; вытянувшуюся петунию в июле обрезают на треть с последующей подкормкой.'],
  [5, 'obrabotka', ['petuniya','barhatcy','kalendula','nasturciya'],
    'Защита летников: петуния — от тли, белокрылки и серой гнили в сырость («Фитоспорин», прореживание); бархатцы почти не поражаются и сами отпугивают нематоду; календула к концу лета часто покрывается мучнистой росой; настурцию оккупируют крестоцветная блошка и капустная белянка (её сажают ловушкой у капусты).'],
  [6, 'urozhay', ['kalendula'],
    'Календулу на лекарственное сырьё собирают всё цветение — полностью раскрытые корзинки каждые 2-3 дня; это заодно продлевает цветение. Сушат в тени.'],
  [7, 'razmnozhenie', ['barhatcy','kalendula','nasturciya','petuniya'],
    'Сбор семян летников — с полностью побуревших сухих корзинок и коробочек в сухую погоду. Сортовые F1-петунии и махровые бархатцы из семян не воспроизводятся; календула и настурция обильно возобновляются самосевом.'],
  [9, 'posev', ['kalendula','barhatcy'],
    'Подзимний посев холодостойких летников (календула, немахровые бархатцы) в конце октября - ноябре по подмёрзшей земле — более раннее и крепкое цветение на следующий год.'],
];

const newEntries = [];
for (const [baseIdx, workType, plants, text] of BASE) {
  for (const region of ['srednyaya-polosa','yug','ural-sibir','severo-zapad']) {
    const mi = shifted(baseIdx, region);
    newEntries.push({
      region, month: MONTH_IDS[mi], monthName: MONTH_NAMES[mi], workType,
      category: 'dekor', plants: plants.join(','), growMethod: 'grunt', text, detail: '', source: SRC,
    });
  }
}

wb.Sheets['Calendar'] = XLSX.utils.json_to_sheet([...calRows, ...newEntries]);
wb.Sheets['Calendar']['!cols'] = [
  { wch: 16 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
  { wch: 24 }, { wch: 14 }, { wch: 60 }, { wch: 50 }, { wch: 40 },
];
XLSX.writeFile(wb, XLSX_PATH);

const by = {};
for (const e of newEntries) by[e.region] = (by[e.region] || 0) + 1;
console.log(`Партия 5 (декор. кустарники и летники): добавлено ${newEntries.length} строк`, JSON.stringify(by));
console.log(`Итого Calendar: ${calRows.length + newEntries.length} строк`);
